; RAM / A5-world symbols. Globals are addressed as negative offsets from A5,
; e.g. `move.w #2,-$38A6(a5)`. Name them here as they are identified:
;   g_example = -$38A6	; word: what it is (evidence: sub_XXXXXX)
g_Player1 = -$1758	; obj: player 1 object ($FFEAA8), vtable at +0 = character class (Player_SetCharacter sets +$9D=0 for it; TAS: Nightcrawler class from frame 180)
g_Player2 = -$1848	; obj: player 2 object ($FFE9B8), +$9D=1; vtable 0 until P2 joins (TAS frame 49140)
g_P1Lives = -$38A8	; word: player 1 lives (9 at new game; decremented on each new life)
g_P2Lives = -$38AA	; word: player 2 lives (9 at new game; decremented on each new life)
g_P1CharIndex = -$3BBC	; byte: P1 character 0 Beast 1 Cyclops 2 Gambit 3 Nightcrawler 4 Psylocke 5 Wolverine 6 Magneto, $FF = not playing (Player_CharIndexOf; TAS RAM vs screenshots)
g_P2CharIndex = -$3BBB	; byte: P2 character index (same encoding as g_P1CharIndex), $FF = not playing
g_P1Health = -$3B94	; word: P1 health carried between scenes (copied from g_Player1+$68 after each scene in Game_SceneLoop; $700 on a new life; 0 = out of play)
g_P2Health = -$3B96	; word: P2 health carried between scenes (from g_Player2+$68; $700 on a new life; 0 = out of play)
g_SceneIndex = -$359C	; word: current scene, index into g_SceneTable (Cerebro screens and stage parts; TAS steps 0,1,2,... per screen)
g_FrameCounter = -$35A2	; long: game frame counter (+1 per frame, +2 when -$38DE set; TAS RAM +60 per 60 frames)
g_SceneTable = -$E52	; 8-byte entries {+0 name string, +4 scene function}, filled by Scene_Register (scene register)
g_SceneCount = -$E54	; byte: number of registered scenes (next free g_SceneTable slot, Scene_Register)
g_SndMute = -$18AC	; byte: non-zero = Snd_Play/Stop/etc. send nothing (set while demos play, loc_005EB8, and around some init calls)
g_MusicTrack = -$38D2	; word: current music track id, -1 = none (Music_Play)
g_Pad1Raw = -$7A8	; word: pad 1 buttons read in V-int (Pad_ReadBoth/Pad_ReadPort: bits 0-3 UDLR, 4-7 B C A Start, 8-11 Z Y X Mode, $4000 6-button, $8000 none)
g_Pad2Raw = -$7A6	; word: pad 2 buttons read in V-int (same encoding as g_Pad1Raw; Pad_IsP2Connected tests bit 15)
g_Pad1Held = -$3A36	; word: P1 buttons held this frame (Pad_Update)
g_Pad2Held = -$3A38	; word: P2 buttons held this frame (Pad_Update)
g_Pad1Pressed = -$3A26	; word: P1 buttons newly pressed this frame (Pad_Update; pause tests $80 Start)
g_Pad2Pressed = -$3A28	; word: P2 buttons newly pressed this frame (Pad_Update)
g_Pad1Released = -$3A2A	; word: P1 buttons released this frame (Pad_Update)
g_Pad2Released = -$3A2C	; word: P2 buttons released this frame (Pad_Update)
g_Pad1Latch = -$3A2E	; word: P1 presses latched while held; game code clears bits to consume them (Pad_Update, sub_15CAA4)
g_Pad2Latch = -$3A30	; word: P2 presses latched while held (Pad_Update)
g_Pad1Accum = -$3A32	; word: P1 buttons OR-accumulated since last cleared (Pad_Update)
g_Pad2Accum = -$3A34	; word: P2 buttons OR-accumulated since last cleared (Pad_Update)
g_DemoActive = -$3A1A	; byte: demo playback on, P1 input comes from g_DemoPad (Pad_Get; set by loc_005EB8)
g_DemoInput = -$3A1E	; ptr: demo input stream of (frame, pad byte) pairs (sub_1F9DE8)
g_DemoPad = -$3A20	; word: current demo pad value for P1 (sub_1F9DE8, Pad_Get)
g_VdpReg1 = -$1D48	; word: VDP mode register 1 command shadow $81xx ($40 display, $20 V-int, $10 DMA) (Sys_InitHardware, VDP_DmaToVram)
g_VdpReg11 = -$204	; word: VDP mode register 3 command shadow $8Bxx, scroll modes (Sys_InitHardware, Scroll_SetParallax)
g_DmaQueue = -$7A4	; array: V-blank DMA queue, $18-byte records of VDP register words (VDP_QueueDma, VDP_FlushDmaQueue)
g_DmaQueueCount = -$7B4	; word: entries in g_DmaQueue (VDP_QueueDma, VDP_ResetDmaQueue)
g_VdpCmdHi = -$7B6	; word: scratch VDP address command high word for a DMA (VDP_DmaPalette)
g_VdpCmdLo = -$7B8	; word: scratch VDP address command low word for a DMA (VDP_DmaPalette)
g_SpriteTable = -$1FDA	; array: sprite attribute buffer ($FFE226, $280 bytes) DMAed to VRAM $F000 every V-blank (VDP_FlushDmaQueue)
g_DmaFlushReq = -$1D4A	; byte: set by game code when g_SpriteTable/g_DmaQueue are ready; VDP_FrameUpdate flushes and clears it
g_PalWork = -$3A00	; 64 words: working palette uploaded to CRAM (Pal_Update, Pal_ApplyFade)
g_PalBase = -$3980	; 64 words: base palette that fades are computed from (Pal_ApplyFade)
g_PalFadeActive = -$3A02	; byte: palette fade in progress (Pal_StartFade, Pal_Update)
g_PalFadeDelay = -$3A04	; word: frames between fade steps (Pal_StartFade sets 4)
g_PalFadeTimer = -$7C4	; word: frames until the next fade step (Pal_Update)
g_PalFadeLevel = -$7BC	; word: current fade level 0-7 (Pal_StartFade, Pal_Update)
g_PalFadeUp = -$7BA	; byte: 1 = fade level counts up, 0 = down (Pal_StartFade)
g_PalFadeLine = -$7BE	; word: palette line being faded, -1 = all four (Pal_ApplyFade)
g_PalFadeTable = -$7C2	; ptr: fade component table, 8 bytes per level (Pal_StartFade)
g_PalWorkDirty = -$7C6	; byte: upload g_PalWork at the next V-blank (Pal_Update clears)
g_PalBaseDirty = -$3A06	; byte: upload g_PalBase at the next V-blank (Pal_Update clears)
g_VBlankCount = -$3A10	; long: V-interrupt counter (+1 in Irq_VBlank; zeroed in Sys_InitHardware)
g_VBlankHook = -$3A14	; ptr: function called from Irq_VBlank every V-int when non-zero (Sys_InitHardware clears; sub_15FA7A saves/sets)
g_VBlankGameHook = -$3A18	; ptr: game function called from Irq_VBlank unless bytes -$38C0/-$359E are set (sub_15B0D0, sub_065E6C)
g_FrameUpdated = -$3A0C	; byte: VDP_FrameUpdate ran this frame (VDP_WaitVBlank clears)
g_HBlankCount = -$BC8	; word: H-interrupt counter (Irq_HBlank)
g_ParallaxDesc = -$3A44	; ptr: current parallax descriptor (Scroll_SetParallax, Scroll_UpdateParallax)
g_HScrollBuf = -$BC6	; array: per-line H-scroll longs ($FFF63A), $380 bytes DMAed to VRAM $F400 (Scroll_UpdateParallax)
g_Camera = -$35B6	; ptr: the CAMERA object (class $1F4960), created by a scene via CAMERA +$0A New(desc, per-frame hook); scenes call its +$36/+$3A (CloneA2_InitCamera)
g_CameraX = -$348E	; word: camera left edge in world pixels (ACTOR Draw: screen x = (x >> 8) - g_CameraX; CAMERA centre = g_CameraX + $A0)
g_CameraY = -$3490	; word: camera top edge in world pixels (ACTOR Draw: screen y = (y >> 8) - g_CameraY; CAMERA centre = g_CameraY + $70)
g_Timers = -$10E8	; 30 x $16-byte timer slots {+0 state, +2 period, +4 next, +8 prev, +$C func, +$10 arg, +$14 byte} (Timer_Create, Timer_RunAll)
g_TimerList = -$10EC	; ptr: head of the active timer list (Timer_Create, Timer_RunAll)
g_TimerCurrent = -$10F0	; ptr: timer whose callback is running (Timer_RunAll)
g_DrawNodes = -$134C	; 30 x $14-byte draw-list nodes {next, prev, func, object, word key, word flags} (DrawList_Init)
g_DrawListHead = -$1350	; ptr: first (lowest key) draw-list node (DrawList_Add, DrawList_DrawAll)
g_DrawListTail = -$1354	; ptr: last draw-list node (DrawList_Add, DrawList_Remove)
g_DrawNodeCursor = -$1358	; ptr: round-robin search start for DrawList_AllocNode
g_HeapTop = -$348C	; ptr: top of the Mem_StackAlloc heap ($FF0000 at Sys_InitHardware)
g_SceneExitTimer = -$359A	; word: frames until the current scene ends, 0 = not ending (Scene_EndAfter; counted down in sub_0656B0)
g_ActivateHook = -$38F0	; ptr: replaces the scene loop's object-activation pass when set (sub_1FA124, Scene_ClearActivateHook)
g_SpriteDefs = -$3886	; array of $14-byte sprite-definition records {+0 flag bits, +2 def ptr, +6 word, +8 word} (Obj_SetSpriteDef)
g_ClassList = -$3900	; ptr: current level class list {word bytes; desc*[]} (ClassList_CallSlot5A/62, sub_1FA7E8)
g_CamShake = -$38A4	; ptr: camera shake script being played, 0 = none: byte pairs (dx, dy) added to g_CameraX/Y per frame; $64 end, $65 n = back n bytes, $66 x = sub_1F945C(x) (sub_088112); e.g. Tbl_CloneA2QuakeScript
g_ScnSiberiaB1 = -$3B70	; byte: scene id of "SiberiaB1 Blizzard" (Scene_RegisterAll); first stage of a new game (Game_ResetPlayers)
g_ScnCerebroSentinels = -$3B7A	; byte: scene id of "CerebroScreen Sentinels" (Scene_RegisterAll)
g_ScnSentinelsD1 = -$3B72	; byte: scene id of "SentinelsD1 Exterior1" (Scene_RegisterAll); also attract demo 3 (Beast)
g_ScnPlayerSelect = -$3B88	; byte: scene id of the last "CerebroScreen PlayerSelect" registration (Scene_RegisterAll; registered between stages); scene after a death (Game_SceneLoop)
g_ScnSentinelsB1 = -$3B74	; byte: scene id of "SentinelsB1 Exterior_3" (Scene_RegisterAll); also attract demo 1 (Cyclops)
g_ScnSentinelsA1 = -$3B76	; byte: scene id of "SentinelsA1 CoolantCore" (Scene_RegisterAll)
g_ScnSentinelsB2 = -$3B78	; byte: scene id of "SentinelsB2 Exterior_Escape" (Scene_RegisterAll)
g_ScnCerebroAvalon = -$3B7C	; byte: scene id of "CerebroScreen Avalon" (Scene_RegisterAll)
g_ScnAvalonB1 = -$3B4A	; byte: scene id of "AvalonB1 Exterior" (Scene_RegisterAll)
g_ScnAvalonB2 = -$3B4C	; byte: scene id of "AvalonB2 InnerShell" (Scene_RegisterAll); also attract demo 2 (Psylocke)
g_ScnAvalonA2 = -$3B4E	; byte: scene id of "AvalonA2 Falling_Room" (Scene_RegisterAll)
g_ScnAvalonA3 = -$3B50	; byte: scene id of "AvalonA3 Exodus" (Scene_RegisterAll)
g_ScnAvalonA4 = -$3B52	; byte: scene id of "AvalonA4 Throne_Room" (Scene_RegisterAll)
g_ScnCerebroBaniMaza = -$3B7E	; byte: scene id of "CerebroScreen BaniMaza" (Scene_RegisterAll)
g_ScnBaniMazaB2 = -$3B54	; byte: scene id of "BaniMazaB2 Exterior" (Scene_RegisterAll)
g_ScnBaniMazaA1 = -$3B56	; byte: scene id of "BaniMazaA1 Moving_Blocks" (Scene_RegisterAll); also attract demo 0 (Nightcrawler)
g_ScnBaniMazaA2 = -$3B58	; byte: scene id of "BaniMazaA2 ApocalypseBoss" (Scene_RegisterAll)
g_ScnCerebroSavage = -$3B80	; byte: scene id of "CerebroScreen Savage" (Scene_RegisterAll)
g_ScnSavageC1 = -$3B5A	; byte: scene id of "SavageC1 Jungle_1" (Scene_RegisterAll)
g_ScnSavageB1 = -$3B5E	; byte: scene id of "SavageB1 Jungle_2" (Scene_RegisterAll)
g_ScnSavageA2 = -$3B60	; byte: scene id of "SavageA2 Perimeter_1" (Scene_RegisterAll)
g_ScnSavageA3 = -$3B62	; byte: scene id of "SavageA3 Perimeter_2" (Scene_RegisterAll)
g_ScnSavageA4 = -$3B64	; byte: scene id of "SavageA4 Chamber" (Scene_RegisterAll)
g_ScnCerebroSpace = -$3B82	; byte: scene id of "CerebroScreen Space" (Scene_RegisterAll)
g_ScnSpaceB1 = -$3B66	; byte: scene id of "SpaceB1 Maintenance_Shaft" (Scene_RegisterAll)
g_ScnSpaceA1 = -$3B68	; byte: scene id of "SpaceA1 Space_Elevator" (Scene_RegisterAll)
g_ScnCerebroClone = -$3B84	; byte: scene id of "CerebroScreen Clone" (Scene_RegisterAll)
g_ScnCloneA1 = -$3B6A	; byte: scene id of "CloneA1 Factory_Floor_1" (Scene_RegisterAll)
g_ScnCloneA2 = -$3B6C	; byte: scene id of "CloneA2 Vertical_Corridor_1" (Scene_RegisterAll)
g_ScnCloneA5 = -$3B6E	; byte: scene id of "CloneA5 BroodBoss" (Scene_RegisterAll)
g_ScnFinalText = -$3B8E	; byte: scene id of "CerebroScreen FinalText" (Scene_RegisterAll)
g_ScnCredits = -$3B86	; byte: scene id of "CerebroScreen Credits" (Scene_RegisterAll); Game_SceneLoop resets the game when g_SceneIndex passes it
g_ScnFailure = -$3B8C	; byte: scene id of "CerebroScreen Failure" (Scene_RegisterAll); game-over screen chosen by Game_SceneLoop
g_ScnLogoAndDemo = -$3B8A	; byte: scene id of "CerebroScreen LogoAndDemo" (Scene_RegisterAll)
g_AttractDemoNum = -$3B90	; word: next attract demo 0-3 (Game_SceneLoop switch -> Game_AttractDemo*; incremented by Game_PlayAttractDemo)
g_ICandyPool = -$1CB2	; ptr: ICandy pool base (ICandy_PoolInit/ICandy_PoolAlloc)
g_ICandyStride = -$1CB4	; word: ICandy pool slot size in bytes (ICandy_PoolInit)
g_ICandyCount = -$1CAE	; word: ICandy pool slot count, 0 = no pool (ICandy_PoolInit)
g_BBoard = -$1CA6	; ptr: BBOARD trigger-flag board, 100 word entries (Switch_ClassInit, Synchronizer_SetFlag)
g_SyncPool = -$1CA2	; ptr: pool of 4 SYNCHRONIZER objects (Synchronizer_New)
g_Elevator = -$3BC4	; ptr: SpaceA1 ELEVATOR object, on SpaceElev_Main's stack (SpaceElev_CameraUpdate)
g_SpawnRecs = -$38DC	; ptr: spawn records, 14 bytes each (sub_15F95C fills them via InitSpawnRec; level loop sub_1FA124)
g_SpawnRecCount = -$38D8	; word: number of spawn records / placement entries (sub_1F98A8, sub_15F95C)
g_PlacementList = -$38D6	; ptr: level placement entries, 16 bytes, word 0 = class index into g_ClassList (sub_1F98A8, sub_15F95C)
